class Solution {
public:
    vector<int> parent;
    vector<int> rnk;

    int find(int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }

    void unite(int x, int y) {
        int px = find(x), py = find(y);
        if (px == py) return;
        if (rnk[px] < rnk[py]) swap(px, py);
        parent[py] = px;
        if (rnk[px] == rnk[py]) rnk[px]++;
    }

    string smallestStringWithSwaps(string s, vector<vector<int>>& pairs) {
        int n = s.size();
        parent.resize(n);
        rnk.resize(n, 0);
        for (int i = 0; i < n; i++) parent[i] = i;

        for (auto& p : pairs) {
            unite(p[0], p[1]);
        }

        vector<vector<int>> components(n);
        for (int i = 0; i < n; i++) {
            components[find(i)].push_back(i);
        }

        for (int r = 0; r < n; r++) {
            if (components[r].empty()) continue;
            int count[26] = {0};
            for (int idx : components[r]) {
                count[s[idx] - 'a']++;
            }
            int pos = 0;
            for (int c = 0; c < 26; c++) {
                while (count[c] > 0) {
                    s[components[r][pos]] = 'a' + c;
                    pos++;
                    count[c]--;
                }
            }
        }

        return s;
    }
};
